var translation = "sakura";
var paragraphField = "sakuraParagraphs";
function address(url) {
  var match = /^https:\/\/(?:n\.)?novelia\.cc\/novel\/(hameln|syosetu|narou|kakuyomu|novelup|alphapolis|pixiv)\/([^/?#]+)(?:[?#].*)?$/.exec(url);
  if (!match) throw new Error('请输入 Novelia 网页版书籍链接');
  return {book: 'https://n.novelia.cc/novel/' + match[1] + '/' + match[2],
    api: 'https://n.novelia.cc/api/novel/' + match[1] + '/' + match[2]};
}
function saveToken(token) {
  if (!/^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(token)) throw new Error('Novelia 未返回有效登录令牌');
  source.putVariable(token);
  source.putLoginHeader(JSON.stringify({Authorization:'Bearer ' + token}));
}
function login() {
  var form = source.getLoginInfoMap();
  var reply = java.post('https://auth.novelia.cc/api/v1/auth/login',
    JSON.stringify({username:String(form.get('username')), password:String(form.get('password')), app:'n'}),
    {'Content-Type':'application/json'});
  saveToken(String(reply.body()).trim());
}
function request(url) {
  var token = source.getVariable();
  try { return JSON.parse(String(java.get(url, token ? {Authorization:'Bearer ' + token} : {}).body())); }
  catch (error) {
    if (!token || String(error).indexOf('HTTP 401') < 0) throw error;
    java.singleFlight('novelia-refresh', function() {
      if (source.getVariable() !== token) return;
      var reply;
      try { reply = java.post('https://auth.novelia.cc/api/v1/auth/refresh?app=n', '', {}); }
      catch (failure) {
        if (String(failure).indexOf('HTTP 401') >= 0) throw new Error('SOURCE_AUTH_EXPIRED:Novelia 登录已过期');
        throw failure;
      }
      saveToken(String(reply.body()).trim());
    }, 15000);
    return JSON.parse(String(java.get(url, {Authorization:'Bearer ' + source.getVariable()}).body()));
  }
}
function title(row) { return translation !== 'jp' && row.titleZh ? row.titleZh : row.titleJp; }
function getBookInfo(book) {
  var url = address(book.bookUrl), data = request(url.api);
  return {name: title(data), author: data.authors.map(function(a) {return a.name;}).join(' / '),
    intro: translation !== 'jp' && data.introductionZh ? data.introductionZh : data.introductionJp,
    kind: ["Sakura"].concat(data.keywords).join(' / '), bookUrl: url.book, tocUrl: url.book};
}
function search(key, page) { return page === 1 ? [getBookInfo({bookUrl: key})] : []; }
function getChapters(book) {
  var url = address(book.bookUrl), data = request(url.api);
  return data.toc.map(function(c, i) {
    return {title: title(c), isVolume: c.chapterId == null,
      url: c.chapterId == null ? url.book + '#volume-' + i : url.api + '/chapter/' + encodeURIComponent(c.chapterId)};
  });
}
function getContent(chapter, book, nextChapterUrl) {
  var data = request(chapter.url), paragraphs = data[paragraphField];
  if (!paragraphs || !paragraphs.length) throw new Error('本章暂无' + "Sakura" + '内容，请切换版本');
  return paragraphs.map(function(p) {return '<p>' + p + '</p>';}).join('\n');
}

function getShelf(page, nextPageUrl) {
  if (!source.getVariable()) throw new Error('请先登录 Novelia');
  var base = 'https://n.novelia.cc/api/user/';
  var query = '?page=' + (page - 1) + '&pageSize=30&sort=update';
  var web = request(base + 'favored-web/all' + query + '&provider=kakuyomu,syosetu,novelup,hameln,pixiv,alphapolis');
  var wenku = request(base + 'favored-wenku/all' + query);
  var items = web.items.map(function(row) {
    return {name:title(row), author:'', kind:row.keywords.join(' / '),
      bookUrl:'https://n.novelia.cc/novel/' + row.providerId + '/' + row.novelId};
  });
  wenku.items.forEach(function(row) {
    items.push({name:translation !== 'jp' && row.titleZh ? row.titleZh : row.title,
      author:'', coverUrl:row.cover, bookUrl:'https://n.novelia.cc/wenku/' + row.id,
      kind:'文库 · 原站阅读', externalOnly:true});
  });
  return {items:items, hasMore:page < Math.max(web.pageNumber, wenku.pageNumber)};
}

function getAccount() {
  if (!source.getVariable()) return {loggedIn:false};
  try { request('https://auth.novelia.cc/api/v1/me/attention-status'); }
  catch (error) {
    if (String(error).indexOf('HTTP 401') >= 0) return {loggedIn:false};
    throw error;
  }
  var payload = source.getVariable().split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
  while (payload.length % 4) payload += '=';
  var user = JSON.parse(java.base64Decode(payload));
  return {loggedIn:true, id:String(user.uid), displayName:user.sub, avatarUrl:''};
}

